-- Phase 2 — Row Level Security
--
-- NOT generated by drizzle-kit. RLS policies, SECURITY DEFINER functions, and GRANT/REVOKE
-- statements are outside what Drizzle's table API can express, so this file is hand-maintained
-- and applied separately from 0000/0001. Apply after 0001, against a fresh database, to fully
-- reproduce what is live.
--
-- This is the FINAL correct version. It was originally applied to the live project as four
-- separate migrations, one of which fixed a real bug (see the note above the GRANT below) —
-- consolidated here so a fresh read isn't confused by that history.
--
-- Two roles: admin (full access) and member (day-to-day work), per build guide §3.7 / the role
-- matrix carried forward from spec §12.3. Every policy follows the
-- supabase-postgres-best-practices skill:
--   - auth.uid() wrapped in (select ...) so it's evaluated once per statement, not per row
--   - TO authenticated explicit, never the deprecated auth.role()
--   - UPDATE policies carry both USING and WITH CHECK
--   - multiple permissive policies for the SAME (table, role, command) are avoided — Postgres
--     evaluates every one of them, so overlapping policies cost real performance for nothing

create schema if not exists private;

-- ---------- role-check helper ----------
-- SECURITY DEFINER is deliberate: without it, this function would need user_roles' OWN select
-- policy to already permit the read for the calling user, which is circular. This is the one
-- sanctioned bypass, and it still checks the calling user's own identity internally.

create or replace function private.is_admin()
returns boolean
language sql
security definer
set search_path = ''
stable
as $$
  select exists (
    select 1 from public.user_roles
    where user_id = (select auth.uid())
      and role = 'admin'
  );
$$;

-- SECURITY DEFINER controls whose privileges the function BODY runs with (bypassing RLS on
-- user_roles). It says nothing about who may CALL the function — that's a separate EXECUTE
-- grant, and every policy below calls this function directly, so `authenticated` must have it.
-- (The live project briefly revoked EXECUTE from authenticated too, which broke every policy
-- that used this function — caught by a functional RLS test immediately after applying, fixed
-- in the same session. Get it right here instead.)
revoke execute on function private.is_admin() from PUBLIC;
grant execute on function private.is_admin() to authenticated;

-- ---------- user_roles ----------
-- Anyone can see who has which role (a 2-6 person team, not sensitive data). Only admins can
-- change roles. The bootstrap admin is seeded directly via SQL — there is deliberately no path
-- for a newly signed-up user to grant themselves admin through these policies.

alter table public.user_roles enable row level security;

create policy user_roles_select on public.user_roles
  for select to authenticated
  using (true);

create policy user_roles_insert on public.user_roles
  for insert to authenticated
  with check ((select private.is_admin()));

create policy user_roles_update on public.user_roles
  for update to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy user_roles_delete on public.user_roles
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- businesses ----------
-- Everyone sees the whole prospect list and can insert (manual entry, discovery jobs). The
-- update policy enforces a real business rule, not just a role check: a member may update a
-- business only while it is unclaimed, or claimed by them. Taking over someone else's claim
-- requires being an admin — the spec's claim rule, enforced at the database rather than left to
-- application code that a forgotten check could silently break.

alter table public.businesses enable row level security;

create policy businesses_select on public.businesses
  for select to authenticated
  using (true);

create policy businesses_insert on public.businesses
  for insert to authenticated
  with check (true);

create policy businesses_update on public.businesses
  for update to authenticated
  using (
    claimed_by is null
    or claimed_by = (select auth.uid())
    or (select private.is_admin())
  )
  with check (
    claimed_by is null
    or claimed_by = (select auth.uid())
    or (select private.is_admin())
  );

create policy businesses_delete on public.businesses
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- identity_keys ----------
-- Read is part of viewing a business; insert supports manual record entry. Mutating or removing
-- an existing key is the table the whole identity model depends on — admin only.

alter table public.identity_keys enable row level security;

create policy identity_keys_select on public.identity_keys
  for select to authenticated
  using (true);

create policy identity_keys_insert on public.identity_keys
  for insert to authenticated
  with check (true);

create policy identity_keys_update on public.identity_keys
  for update to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy identity_keys_delete on public.identity_keys
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- field_metadata ----------

alter table public.field_metadata enable row level security;

create policy field_metadata_select on public.field_metadata
  for select to authenticated
  using (true);

create policy field_metadata_insert on public.field_metadata
  for insert to authenticated
  with check (true);

create policy field_metadata_update on public.field_metadata
  for update to authenticated
  using (true)
  with check (true);

create policy field_metadata_delete on public.field_metadata
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- exclusions ----------
-- Members need to SEE why a business is excluded. Editing the list is Admin-only per the role
-- matrix. Insert/update/delete are separate policies (not `for all`) so they don't overlap with
-- the select policy for the same role — see the "multiple permissive policies" note above.

alter table public.exclusions enable row level security;

create policy exclusions_select on public.exclusions
  for select to authenticated
  using (true);

create policy exclusions_insert on public.exclusions
  for insert to authenticated
  with check ((select private.is_admin()));

create policy exclusions_update on public.exclusions
  for update to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy exclusions_delete on public.exclusions
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- suppression_hashes ----------
-- Admin-only even for SELECT. This table exists to prevent re-contacting someone who asked to
-- be forgotten — it carries no useful information for day-to-day work, only for compliance.

alter table public.suppression_hashes enable row level security;

create policy suppression_hashes_admin_only on public.suppression_hashes
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

-- ---------- merge_snapshots ----------
-- The restricted audit trail for reversing a bad merge. Written by the merge job (service role,
-- bypasses RLS entirely); read only by an admin investigating a merge.

alter table public.merge_snapshots enable row level security;

create policy merge_snapshots_admin_only on public.merge_snapshots
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

-- ---------- runs ----------
-- Any member can start a search and see run history. Stage/status/spend fields are normally
-- updated by the pipeline job (service role); admin-only manual correction covers the rare case
-- that needs a human fix.

alter table public.runs enable row level security;

create policy runs_select on public.runs
  for select to authenticated
  using (true);

create policy runs_insert on public.runs
  for insert to authenticated
  with check (true);

create policy runs_update on public.runs
  for update to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy runs_delete on public.runs
  for delete to authenticated
  using ((select private.is_admin()));

-- ---------- provider_calls ----------
-- The cost ledger. "View audit logs: Limited" for members per the role matrix — admin-only for
-- v1 rather than building a separate limited view.

alter table public.provider_calls enable row level security;

create policy provider_calls_admin_only on public.provider_calls
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

-- ---------- outcomes ----------
-- Logging outreach is core day-to-day work for every member.

alter table public.outcomes enable row level security;

create policy outcomes_select on public.outcomes
  for select to authenticated
  using (true);

create policy outcomes_insert on public.outcomes
  for insert to authenticated
  with check (true);

create policy outcomes_update on public.outcomes
  for update to authenticated
  using (true)
  with check (true);

create policy outcomes_delete on public.outcomes
  for delete to authenticated
  using ((select private.is_admin()));
